guidance.correct_example:
def traverse(a_node: TreeNode, a_depth: int = 0, a_max_depth: int = 100) -> Result[list]:
    if a_depth >= a_max_depth:
        return Result.failure(f'Max recursion depth {a_max_depth} exceeded')
    result = [a_node.value]
    for child in a_node.children:
        child_result = traverse(child, a_depth + 1, a_max_depth)
        if not child_result.is_success():
            return child_result
        result.extend(child_result.value)
    return Result.success(result)

guidance.incorrect_example:
def traverse(a_node: TreeNode) -> list:
    result = [a_node.value]
    for child in a_node.children:
        result.extend(traverse(child))
    return result
